#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<long long> a(n), P(n + 1, 0);
    for (auto& x : a) cin >> x;
    for (int i = 0; i < n; i++) P[i + 1] = P[i] + a[i];
    while (q--) {
        int l, r;
        cin >> l >> r;
        cout << l << ' ' << r << ' ' << P[r + 1] - P[l] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<vector<int>> g = {{1, 2, 3, 4}, {5, 6, 7, 8}, {9, 1, 2, 3}};
    int n = g.size(), m = g[0].size();
    vector<vector<long long>> S(n + 1, vector<long long>(m + 1, 0));
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            S[i + 1][j + 1] = S[i][j + 1] + S[i + 1][j] - S[i][j] + g[i][j];
    auto rect = [&](int r1, int c1, int r2, int c2) {
        return S[r2 + 1][c2 + 1] - S[r1][c2 + 1] - S[r2 + 1][c1] + S[r1][c1];
    };
    cout << rect(0, 0, 2, 3) << '\n' << rect(1, 1, 2, 2) << '\n' << rect(2, 0, 2, 0) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 8;
    vector<long long> D(n + 1, 0);
    vector<array<int, 3>> ups = {{1, 3, 5}, {2, 7, 1}, {0, 0, -2}, {5, 7, 10}};
    for (auto [l, r, v] : ups) {
        D[l] += v;
        D[r + 1] -= v;
    }
    long long cur = 0;
    for (int i = 0; i < n; i++) {
        cur += D[i];
        cout << cur << ' ';
    }
    cout << '\n';

    vector<int> big = {2000000000, 2000000000};
    cout << accumulate(big.begin(), big.end(), 0LL) << '\n';
    return 0;
}

